import sys

def pow(i, j):
	s = i + j
	if i % 2 == 0:
		return 0
	return 2 ** s

def nxt():
	s = input()
	while not s:
		s = input()
	return int(s)

def main():
	(n,) = map(int, input().split(' '))
	a = []
	for i in range(n):
		b = []
		for j in range(n):
			z = pow(i, j)
			b.append(z)
			print(z, end=' ')
		a.append(b)
		print()
	sys.stdout.flush()
	for _ in range(nxt()):
		k = nxt()
		i = 0
		j = 0
		print(1, 1)
		while i < n - 1 or j < n - 1:
			if i == n - 1:
				j += 1
			elif j == n - 1:
				i += 1
			elif a[i + 1][j] > 0:
				if a[i + 1][j] & k == a[i + 1][j]:
					i += 1
				else:
					j += 1
			elif a[i][j + 1] & k == a[i][j + 1]:
				j += 1
			else:
				i += 1
			print(i + 1, j + 1)
		print()
		sys.stdout.flush()
main()
